/* O número de um pedido que ESTÁ no Arquivo. Troque pelo que
   aparecer na sua tela — o do print era 37136684. */
return [{ json: { numero: '37136684' } }];

/* SONDA — a API alcança o Arquivo pedindo pelo NÚMERO?

   A investigação de 22/08 concluiu que o Arquivo é inalcançável, e testou
   três caminhos: date_from de janeiro, id_from 1 e filtro por status. Os
   três devolvem o mesmo pedido de 24/05, o mais antigo ATIVO.

   Falta um: pedir um pedido arquivado pelo número exato. É diferente dos
   outros porque não é varredura — é busca direta, e algumas APIs atendem
   por id o que não listam por intervalo.

   Se voltar o pedido, o Arquivo inteiro é alcançável e dá para montar um
   fluxo. Se voltar vazio, aí sim o CSV é o único caminho e a conclusão de
   agosto está completa. */
const alvo = String($('Escolher o pedido').first().json.numero || '');
const r = $json || {};

if (r.status !== 'SUCCESS') {
  return [{ json: { veredito: 'A BASE RECUSOU', detalhe: r.error_message || r.error_code || JSON.stringify(r).slice(0,300) } }];
}

const pedidos = r.orders || [];
const achado = pedidos.find(p => String(p.order_id) === alvo);

if (achado) {
  const d = achado.date_confirmed || achado.date_add;
  return [{ json: {
    veredito: 'ALCANÇA — a API devolve pedido arquivado pelo número',
    order_id: achado.order_id,
    data: d ? new Date(Number(d) * 1000).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '(sem data)',
    cliente: achado.delivery_fullname || achado.invoice_fullname || '',
    origem: (achado.order_source || '') + '/' + (achado.order_source_id === undefined ? '' : achado.order_source_id),
    proximoPasso: 'Me manda esta saída: dá para montar o fluxo do Arquivo.'
  } }];
}

return [{ json: {
  veredito: 'NÃO ALCANÇA — a API não devolve pedido arquivado nem pelo número',
  pedidosQueVieram: pedidos.length,
  primeiro: pedidos.length ? String(pedidos[0].order_id) : '(nenhum)',
  proximoPasso: 'Confirma a conclusão de agosto: o Arquivo só sai pelo CSV da tela.'
} }];
